{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM 被明确请求参与组织行为；这里的参与来自谓词绑定，而非角色名称本身。",
      "sources": [{"quote": "请 PM 组织读取", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "“请”支持请求性要求，“组织”是明确的主谓词；其对形成行为的管辖范围仍有歧义。",
      "sources": [{"quote": "请 PM 组织读取 license.csv 并形成 license-note.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "read",
      "verdict": "SUPPORT",
      "reason": "读取是被要求组织的实际行为，属于组织的补足内容；未明确指定读取的具体执行者。",
      "sources": [{"quote": "组织读取 license.csv", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "license_csv",
      "verdict": "SUPPORT",
      "reason": "文件明确作为读取输入出现，支持该使用关系中的只读输入分类；这不构成对文件其他用途的全面修改禁令。",
      "sources": [{"quote": "读取 license.csv", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "generate",
      "verdict": "SUPPORT",
      "reason": "形成文件是要求的产出行为。将它解析为组织的并列补足内容有文字支持，但其 COMPLEMENT 层及 organize 所有者不是唯一读法。",
      "sources": [{"quote": "请 PM 组织读取 license.csv 并形成 license-note.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "license_note",
      "verdict": "SUPPORT",
      "reason": "“形成”明确将该文件绑定为生成输出，没有将它描述为既有输入。",
      "sources": [{"quote": "形成 license-note.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "unclear_entries",
      "verdict": "SUPPORT",
      "reason": "条目由许可证范围不清楚这一属性限定，并作为必须标记的受影响材料；标记存储在哪个文件中未说明。",
      "sources": [{"quote": "许可证范围不清楚的条目必须标记为“待确认”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "unclear_scope",
      "verdict": "SUPPORT",
      "reason": "这是限定条目的属性状态，不是独立要求执行的业务行为。",
      "sources": [{"quote": "许可证范围不清楚的条目", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "mark",
      "verdict": "SUPPORT",
      "reason": "“必须”明确要求标记行为；具体执行者未明示。",
      "sources": [{"quote": "必须标记为“待确认”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "pending_label",
      "verdict": "SUPPORT",
      "reason": "这是要求使用的标记内容，不是要求另行实施确认行为。",
      "sources": [{"quote": "标记为“待确认”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "automatic_classification",
      "verdict": "SUPPORT",
      "reason": "禁止的是自动判为可商用这一具体行为；FORBIDDEN 配合肯定形式的行为描述支持该表示，不应扩大为禁止全部判定。",
      "sources": [{"quote": "不得自动判为可商用", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "commercial_label",
      "verdict": "SUPPORT",
      "reason": "“可商用”是被禁止的自动判定内容，不是源文断言条目实际具备的状态。",
      "sources": [{"quote": "不得自动判为可商用", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM 明确执行组织行为，没有据角色名称推断审批权或其他行为的执行责任。",
      "sources": [{"quote": "PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r2",
      "verdict": "SUPPORT",
      "reason": "读取直接位于组织的补足内容中，支持结构性从属关系。",
      "sources": [{"quote": "组织读取 license.csv", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r3",
      "verdict": "SUPPORT",
      "reason": "将读取与形成共同放入组织范围是可支持的读法，但并列也可发生在“组织读取”与“形成”之间；该关系不能排除后一读法。",
      "sources": [{"quote": "请 PM 组织读取 license.csv 并形成 license-note.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r4",
      "verdict": "SUPPORT",
      "reason": "“并”支持读取与形成的并列联系，但不足以独自确定并列层级，也没有明确规定执行先后。",
      "sources": [{"quote": "组织读取 license.csv 并形成 license-note.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r5",
      "verdict": "SUPPORT",
      "reason": "license.csv 是读取的直接对象，不是依据、方法或生成结果。",
      "sources": [{"quote": "读取 license.csv", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r6",
      "verdict": "SUPPORT",
      "reason": "license-note.md 明确是形成行为的结果。",
      "sources": [{"quote": "形成 license-note.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r7",
      "verdict": "SUPPORT",
      "reason": "属性短语将许可证范围不清楚绑定到这些条目；该关系未把属性提升为独立行动。",
      "sources": [{"quote": "许可证范围不清楚的条目", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r8",
      "verdict": "SUPPORT",
      "reason": "必须标记的对象明确是许可证范围不清楚的条目。",
      "sources": [{"quote": "许可证范围不清楚的条目必须标记为“待确认”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r9",
      "verdict": "SUPPORT",
      "reason": "“待确认”明确绑定为标记内容。",
      "sources": [{"quote": "标记为“待确认”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r10",
      "verdict": "SUPPORT",
      "reason": "同一句中连续谓词共享前置的条目话题，支持将自动判定禁令限定于这些条目。",
      "sources": [{"quote": "许可证范围不清楚的条目必须标记为“待确认”，不得自动判为可商用", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r11",
      "verdict": "SUPPORT",
      "reason": "“可商用”明确是自动判定的内容，处于禁止行为内部。",
      "sources": [{"quote": "不得自动判为可商用", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r12",
      "verdict": "SUPPORT",
      "reason": "“不得”支持任务约束对该自动判定行为的禁止；TASK 是结构性任务根，不代表另有具名授权者。",
      "sources": [{"quote": "不得自动判为可商用", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    }
  ],
  "findings": [
    {
      "id": "f1",
      "kind": "AMBIGUITY_COLLAPSED",
      "candidate_ids": ["organize", "generate", "r3", "r4"],
      "sources": [{"quote": "请 PM 组织读取 license.csv 并形成 license-note.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
      "reason": "图仅保留“PM 组织［读取并形成］”，没有保留“PM［组织读取］并［形成］”这一并列附着读法。后者使形成成为 PM 的并列主行动，前者仅明确 PM 组织形成、未明确实际形成者。两种读法均要求形成文件，但组织范围、事件层级与执行者绑定不同；不能据现有文本消除该歧义。"
    }
  ],
  "coverage": [
    {
      "region_id": "c1",
      "disposition": "AMBIGUOUS",
      "candidate_ids": ["pm", "organize", "read", "license_csv", "generate", "license_note", "unclear_entries", "unclear_scope", "mark", "pending_label", "automatic_classification", "commercial_label", "r1", "r2", "r3", "r4", "r5", "r6", "r7", "r8", "r9", "r10", "r11", "r12"],
      "reason": "已覆盖读取输入、形成输出、限定条目的属性、强制标记内容及自动商用判定禁令。首句中形成行为的并列附着及对应执行者仍有未保留的竞争读法，因此整个唯一源区域不能记为已可靠解析。源文未说明条目所在文件、标记存储位置，也未要求另行确认；这些未知不能通过跨句猜测补全。"
    }
  ],
